import re

def evaluate_agent(agent, test_cases, metrics):
    results = []
    for tc in test_cases:
        result = agent(tc["input"])
        results.append(result)
    correct = 0
    tool_calls = 0
    total_steps = 0
    for i, tc in enumerate(test_cases):
        r = results[i]
        if isinstance(r, dict):
            output = r.get("answer", r.get("result", ""))
            tool_calls += 1 if r.get("tool") else 0
            total_steps += len(r.get("trajectory", []))
        else:
            output = str(r)
        if output.strip().lower() == tc["expected"].strip().lower():
            correct += 1
    n = len(test_cases)
    return {"accuracy": correct / n, "tool_call_rate": tool_calls / n, "avg_steps": total_steps / n, "total_cases": n}
